    "onboarding.s1.subtitle": "Ein Arbeitsbereich, der sich dir anpasst.",
    "onboarding.s1.description": "Alles, was du zum Denken, Planen und Gestalten brauchst - Gewohnheiten, Dokumente, Tagebuch und Aufgaben - in einem ruhigen, fokussierten Raum. Kein Ballast, kein Durcheinander, kein Lärm.",
    "onboarding.s1.label": "Dein Arbeitsbereich",
    "onboarding.s2.title": "Deine Werkzeuge",
    "onboarding.s2.subtitle": "Vier Bereiche, ein Gehirn.",
    "onboarding.s2.description": "Gewohnheiten schaffen Schwung. Dokumente halten Ideen fest. Das Tagebuch lädt zum Reflektieren ein. Aufgaben erledigen Dinge. Nutze, was du brauchst, ignoriere den Rest - jedes für sich ist tief.",
