    "onboarding.s3.subtitle": "Alles lebt auf deinem Gerät.",
    "onboarding.s3.description": "Keine Konten, keine Abos, kein Tracking. Deine Daten verlassen nie deinen Browser - das Einzige, was ihn verlässt, ist eine Anfrage, wenn du mit Noor sprichst, und selbst die ist temporär.",
    "onboarding.s3.label": "Lokal zuerst. Von Natur aus privat.",
