export function t(lang: string, key: string): string {
  const table = dict[lang] || dict.en;
  return table[key] || dict.en[key] || key;
}

export function getLangDir(lang: string): "ltr" | "rtl" {
  return (LANGUAGES.find((l) => l.code === lang) || LANGUAGES[0]).dir;
}

/** Reactive language hook - re-renders whenever the language changes. */
export function useI18n() {
  // Hydration-safe: server and first client render both use "en",
  // so there is never a markup mismatch. The stored language is
  // applied right after mount in the effect below.
  const [lang, setLang] = useState<string>("en");

  useEffect(() => {
    const apply = () => {
      setLang((storage.getData().theme.language as string) || "en");
    };
    apply();
    const unsub = storage.subscribe(apply);
    return unsub;
  }, []);

  return { lang, t: (key: string) => t(lang, key), dir: getLangDir(lang) };
}
